head.script:
///////// 1. 변수 및 선언 영역 /////////
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.bns.BnsPanelToGroupBox(panel_Top);
        edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : btn_Search > onclick
         * 설명      : 조회버튼 클릭
         ***********************************************/
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20300.btn_Search_onclick" });
    }
};

