/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        /**********************************************
         * 함수명   : txb_ISUR_CD > onblur
         * 설명      : 발행기관 코드 변경
         ***********************************************/
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20300.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        /**********************************************
         * 함수명   : txb_ISU_CD > onblur
         * 설명      : 종목 코드 변경
         ***********************************************/
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20300.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
