/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        /**********************************************
         * 함수명   : dts_List > OnLoadError
         * 설명      : dts_List 조회 에러
         ***********************************************/
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20300.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        /**********************************************
         * 함수명   : dts_List > OnLoadError
         * 설명      : dts_List 조회 성공
         ***********************************************/
        let sumNoTermYafFee = 0;
        let sumRpayYafAmt = 0;
        let minSumFeeAmt = 0;
        for (let i = 1; i <= dts_List.getRowCount(); i++) {
            sumNoTermYafFee += Number(dts_List.getCellData(i, "BND_ANULFEE_MIN"));
        }
        if (cmb_GrpYn.getValue() !== "N") {
            sumRpayYafAmt = await scwin.rpayAmt();
        }
        minSumFeeAmt = sumNoTermYafFee - sumRpayYafAmt;
        grd_List.Redraw = false;
        dts_List.insertRow();
        dts_List.setCellData(rowcount + 1, "ISU_NM", "소계(①)");
        dts_List.setCellData(rowcount + 1, "BND_ANULFEE_MIN", sumNoTermYafFee);
        dts_List.insertRow();
        dts_List.setCellData(rowcount + 2, "ISU_NM", "연부과금 환급금 총액(②)");
        dts_List.setCellData(rowcount + 2, "BND_ANULFEE_MIN", sumRpayYafAmt);
        dts_List.insertRow();
        dts_List.setCellData(rowcount + 3, "ISU_NM", "선수수익 총액(① - ②)");
        dts_List.setCellData(rowcount + 3, "BND_ANULFEE_MIN", minSumFeeAmt);
        $c.stf.fillGridHeaderTotalCnt(rowcount + 3, panel_page);

        // grd_List.ColumnProp('NO','value') = "{decode(ISU_NM,'소계(①)','')}";
        $c.cm.setColumnProp(grd_List, 'NO', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'GRP_YN', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'ISU_NM', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'BND_ANULFEE', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'BND_TREM_AMT', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'BND_ANULFEE_MIN', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'TERM', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'ISU_CD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'ISU_DD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'REDMPT_DD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'GRP_CNT', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        $c.cm.setColumnProp(grd_List, 'GRP_TYP', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
        grd_List.Redraw = false;
        dts_List.setRowPosition(1, 0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20300.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_RpayAmt_OnLoadError
 * @description dts_RpayAmt 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_RpayAmt_OnLoadError = async function() {
    try {
        /**********************************************
         * Event   : dts_RpayAmt > OnLoadError
         * 설명    : dts_RpayAmt 조회에러시 처리
         ***********************************************/
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20300.dts_RpayAmt_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_RpayAmt_OnLoadCompleted
 * @description dts_RpayAmt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_RpayAmt_OnLoadCompleted = function(rowcount) {
    /**********************************************
     * Event   : dts_RpayAmt > OnLoadCompleted
     * 설명    : dts_RpayAmt 조회성공시 처리
     ***********************************************/
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 일자 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ANUL_FEE_PRE_INCOM_LIST";
    url += "&queryId=lds.stf.bnsanul_fee_pre_incom.select.list";
    url += "&SCREN_ID=" + "ULDBNS20300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + txb_ISUR_CD.getValue();
    url += "&{P}V_ISU_NM=" + txb_ISU_CD.getValue();
    url += "&{P}V_GRP_YN=" + cmb_GrpYn.getValue();
    url += "&{P}V_STD_DT=" + edt_SDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name rpayAmt
 * @description 연부과금 환급금 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rpayAmt = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ANUL_FEE_PRE_INCOM_LISTAMT";
    url += "&queryId=lds.stf.bnsanul_fee_pre_incom.select.listamt";
    url += "&SCREN_ID=" + "ULDBNS20300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_DT=" + edt_SDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_RpayAmt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_RpayAmt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return Number(dts_RpayAmt.getCellData(0, "YAF_RPAY_AMT"));
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_ISUR_CD.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_COM_NM.setValue(arrPar[0].ISUR_NM);
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {*} img_CoSearch img_CoSearch
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(img_CoSearch) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(img_CoSearch);
};

/**
 * @method
 * @name setParForIsuCd
 * @description 종목선택목록 세팅
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};

/**
 * @method
 * @name getParListBndIsu
 * @description 상장종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISUR_NM: txb_ISUR_CD.getValue(),
        ISU_NM: txb_ISU_CD.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParListBndIsu
 * @description 상장종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParListBndIsu = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].STD_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS20300.xml", SCREN_PROCS_TP_CD_07);
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_연부과금 선수수익 조회.xls";
        // jackal_19.09.27  속도개선을 위해 수정 SaveExcel -> GridToExcel
        $c.data.downloadGridViewExcel(grd_List, {fileName: "연부과금 선수수익 조회", type: "8"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
